"use client";

import { useState } from 'react';
import { X, ChevronLeft, ChevronRight, ChevronUp, ChevronDown } from 'lucide-react';
import { CommentSection } from '@/components/comment-section';
import type { Comic } from '@/lib/types';
import { MediaRenderer } from '@/components/media-renderer';

interface ComicModalProps {
  comic: Comic;
  onClose: () => void;
}

export function ComicModal({ comic, onClose }: ComicModalProps) {
  const [currentPage, setCurrentPage] = useState(0);
  const [showComments, setShowComments] = useState(false);

  // 현재는 여러 이미지/파일이 있어도 무조건 세로 스크롤로 표시해달라는 요청이 있었으므로,
  // long 타입(로그 백업) 역시 단편과 동일하게 세로로 길게 보여줍니다.
  const isVerticalView = true;

  const nextPage = () => {
    setCurrentPage((prev) => 
      prev < comic.images.length - 1 ? prev + 1 : prev
    );
  };

  const prevPage = () => {
    setCurrentPage((prev) => 
      prev > 0 ? prev - 1 : prev
    );
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-foreground/90"
        onClick={onClose}
      />
      
      {/* Modal */}
      <div className="relative w-full h-full flex flex-col">
        {/* Header */}
        <div className="relative z-10 flex items-center justify-between p-4 bg-gradient-to-b from-foreground/50 to-transparent">
          <div className="text-card drop-shadow-md">
            <h2 className="text-lg font-bold">{comic.title}</h2>
            <p className="text-sm text-card/80">
              {isVerticalView ? `${comic.images.length}개의 포스트/미디어` : `${currentPage + 1} / ${comic.images.length} 페이지`}
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl bg-card/20 hover:bg-card/30 text-card transition-colors z-50"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Comic Viewer */}
        {!isVerticalView ? (
          <div className="flex-1 flex items-center justify-center px-4 pb-4 relative">
            {/* Navigation - Previous */}
            <button
              onClick={prevPage}
              disabled={currentPage === 0}
              className="absolute left-4 top-1/2 -translate-y-1/2 p-3 rounded-xl bg-card/20 hover:bg-card/30 text-card transition-colors disabled:opacity-30 disabled:cursor-not-allowed z-10"
            >
              <ChevronLeft className="w-6 h-6" />
            </button>

            {/* Image */}
            <div className="max-w-4xl max-h-[80vh] flex items-center justify-center">
              <MediaRenderer
                src={comic.images[currentPage]}
                alt={`${comic.title} - 페이지 ${currentPage + 1}`}
                className="max-w-full max-h-[80vh] object-contain rounded-lg shadow-2xl"
              />
            </div>

            {/* Navigation - Next */}
            <button
              onClick={nextPage}
              disabled={currentPage === comic.images.length - 1}
              className="absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded-xl bg-card/20 hover:bg-card/30 text-card transition-colors disabled:opacity-30 disabled:cursor-not-allowed z-10"
            >
              <ChevronRight className="w-6 h-6" />
            </button>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto px-4 pb-24 relative flex flex-col items-center gap-0">
            {comic.images.map((imgSrc, index) => (
              <MediaRenderer
                key={index}
                src={imgSrc}
                alt={`${comic.title} - 미디어 ${index + 1}`}
                className="max-w-3xl w-full object-contain"
              />
            ))}
          </div>
        )}

        {/* Page indicator (only for long comics conceptually, actually disabled here via isVerticalView check) */}
        {!isVerticalView && (
          <div className="absolute bottom-20 left-1/2 -translate-x-1/2 flex gap-1">
            {comic.images.map((_, index) => (
              <button
                key={index}
                onClick={() => setCurrentPage(index)}
                className={`w-2 h-2 rounded-full transition-colors ${
                  index === currentPage ? 'bg-primary' : 'bg-card/40'
                }`}
              />
            ))}
          </div>
        )}

        {/* Comments Toggle Button */}
        <button
          onClick={() => setShowComments(!showComments)}
          className="absolute bottom-4 right-4 flex items-center gap-2 px-4 py-2 rounded-xl bg-card text-foreground shadow-lg hover:shadow-xl transition-shadow"
        >
          {showComments ? (
            <>
              <ChevronDown className="w-4 h-4" />
              댓글 닫기
            </>
          ) : (
            <>
              <ChevronUp className="w-4 h-4" />
              댓글 보기
            </>
          )}
        </button>

        {/* Comments Panel */}
        {showComments && (
          <div className="absolute bottom-16 right-4 w-80 max-h-96 bg-card rounded-xl shadow-xl overflow-hidden">
            <div className="max-h-96 overflow-y-auto">
              <CommentSection postId={comic.id} postType="comic" />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
