"use client";

import { useState } from 'react';
import { useAppStore } from '@/lib/store';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { MessageCircle, Send, Trash2 } from 'lucide-react';

interface CommentSectionProps {
  postId: string;
  postType: 'illustration' | 'comic';
}

export function CommentSection({ postId, postType }: CommentSectionProps) {
  const { comments, addComment, removeComment, isAdmin } = useAppStore();
  const [author, setAuthor] = useState('');
  const [content, setContent] = useState('');

  const postComments = comments.filter(
    (c) => c.postId === postId && c.postType === postType
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!author.trim() || !content.trim()) return;

    addComment({
      id: Date.now().toString(),
      postId,
      postType,
      author: author.trim(),
      content: content.trim(),
      createdAt: new Date().toISOString(),
    });

    setContent('');
  };

  return (
    <div className="p-4">
      {/* Header */}
      <div className="flex items-center gap-2 mb-4">
        <MessageCircle className="w-4 h-4 text-muted-foreground" />
        <span className="text-sm font-medium">
          댓글 {postComments.length}개
        </span>
      </div>

      {/* Comment Form */}
      <form onSubmit={handleSubmit} className="mb-4 space-y-2">
        <Input
          value={author}
          onChange={(e) => setAuthor(e.target.value)}
          placeholder="닉네임"
          className="text-sm bg-input"
        />
        <div className="flex gap-2">
          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="댓글을 작성하세요..."
            rows={2}
            className="resize-none text-sm bg-input flex-1"
          />
          <Button 
            type="submit" 
            size="icon"
            disabled={!author.trim() || !content.trim()}
          >
            <Send className="w-4 h-4" />
          </Button>
        </div>
      </form>

      {/* Comments List */}
      <div className="space-y-3">
        {postComments.length > 0 ? (
          postComments.map((comment) => (
            <div 
              key={comment.id} 
              className="p-3 rounded-xl bg-muted/50"
            >
              <div className="flex items-center justify-between mb-1">
                <span className="text-sm font-medium">{comment.author}</span>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground">
                    {new Date(comment.createdAt).toLocaleDateString('ko-KR')}
                  </span>
                  {isAdmin && (
                    <button
                      onClick={() => removeComment(comment.id)}
                      className="p-1 text-destructive hover:bg-destructive/10 rounded"
                    >
                      <Trash2 className="w-3 h-3" />
                    </button>
                  )}
                </div>
              </div>
              <p className="text-sm text-muted-foreground whitespace-pre-wrap">
                {comment.content}
              </p>
            </div>
          ))
        ) : (
          <p className="text-sm text-muted-foreground text-center py-4">
            아직 댓글이 없습니다. 첫 댓글을 남겨보세요!
          </p>
        )}
      </div>
    </div>
  );
}
